using UnityEngine;using Alterverse.Characters;using Alterverse.Visuals;
namespace Alterverse.UI
{
public sealed class MainMenuController:MonoBehaviour
{
private enum Page{Home,Heroes,Settings}private static MainMenuController instance;private Page page;private bool visible=true,launching;private GUIStyle title,subtitle,button,primary,small,panel,heroName,sideLabel;private Texture2D dimTexture,zeroTexture,lumenTexture,whiteTexture;private int selectedHero;private float openedAt,launchAt;private readonly string[] heroes={"VEYR","KAELON","NYRA","ELYRA","MIRA","ROOK"};private readonly string[] roles={"ASSASSINE","TANK","MARKSMAN","MAGIER","SUPPORT","BRUISER"};
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<MainMenuController>()==null)new GameObject("DF_MainMenu").AddComponent<MainMenuController>();}private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;selectedHero=(int)PlayerHeroSelection.Selected;openedAt=Time.unscaledTime;Time.timeScale=0;dimTexture=MakeTexture(StylizedArtDirection.Ink);zeroTexture=MakeTexture(StylizedArtDirection.ZeroDark);lumenTexture=MakeTexture(StylizedArtDirection.LumenDark);whiteTexture=MakeTexture(Color.white);}private void Update(){if(launching&&Time.unscaledTime-launchAt>.62f)EnterMatch();}
private Texture2D MakeTexture(Color c){Texture2D t=new(1,1);t.SetPixel(0,0,c);t.Apply();return t;}private void OnDestroy(){if(instance==this)instance=null;DestroyTexture(dimTexture);DestroyTexture(zeroTexture);DestroyTexture(lumenTexture);DestroyTexture(whiteTexture);}private static void DestroyTexture(Texture2D t){if(t!=null)Destroy(t);}private void OnGUI(){if(!visible)return;EnsureStyles();DrawBackground();if(launching){DrawLaunch();return;}switch(page){case Page.Heroes:DrawHeroes();break;case Page.Settings:DrawSettings();break;default:DrawHome();break;}}
private void DrawBackground(){GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),dimTexture);float t=Time.unscaledTime-openedAt,pulse=.5f+.5f*Mathf.Sin(t*1.35f),collision=Mathf.Sin(t*.7f)*Screen.width*.006f;GUI.color=Color.white;GUI.DrawTexture(new Rect(0,0,Screen.width*.505f+collision,Screen.height),zeroTexture);GUI.DrawTexture(new Rect(Screen.width*.495f+collision,0,Screen.width*.505f,Screen.height),lumenTexture);float center=Screen.width*.5f+collision;for(int i=0;i<12;i++){float phase=t*(.55f+i*.025f)+i*1.37f,y=(i+.4f)*Screen.height/12f+Mathf.Sin(phase*1.7f)*15,x=center+Mathf.Sin(phase)*14;GUI.color=i%2==0?new Color(StylizedArtDirection.ZeroEnergy.r,StylizedArtDirection.ZeroEnergy.g,StylizedArtDirection.ZeroEnergy.b,.25f+.2f*pulse):new Color(StylizedArtDirection.LumenEnergy.r,StylizedArtDirection.LumenEnergy.g,StylizedArtDirection.LumenEnergy.b,.25f+.2f*pulse);GUI.DrawTexture(new Rect(x-2,y-18,4,36),whiteTexture);}GUI.color=Color.white;GUI.DrawTexture(new Rect(center-(3+5*pulse)*.5f,0,3+5*pulse,Screen.height),whiteTexture);DrawComicCuts(center,t);GUI.Label(new Rect(18,Screen.height*.48f,Screen.width*.22f,32),"DIMENSION ZERO",sideLabel);GUI.Label(new Rect(Screen.width*.78f-18,Screen.height*.48f,Screen.width*.22f,32),"LUMEN",sideLabel);}
private void DrawComicCuts(float center,float t){for(int i=0;i<5;i++){float y=Screen.height*(.13f+i*.18f),drift=Mathf.Sin(t*.45f+i)*8;GUI.color=new Color(1,1,1,.07f);GUI.DrawTexture(new Rect(0,y+drift,center*.7f,2),whiteTexture);GUI.DrawTexture(new Rect(center+center*.3f,y-drift,Screen.width-(center+center*.3f),2),whiteTexture);}GUI.color=Color.white;}
private void DrawHome(){float w=Mathf.Min(720,Screen.width*.9f),x=(Screen.width-w)*.5f,top=Screen.height*.09f;GUI.Label(new Rect(x,top,w,92),"DIMENSIONS FRONT",title);GUI.Label(new Rect(x,top+82,w,34),"FIGHT FOR YOUR REALITY",subtitle);float cardW=Mathf.Min(180,Screen.width*.2f),cardH=Mathf.Min(230,Screen.height*.29f);StylizedHeroCard.Draw(new Rect(Screen.width*.5f-cardW*.5f,top+125,cardW,cardH),(HeroId)selectedHero,whiteTexture,Time.unscaledTime);GUI.Label(new Rect(x,top+125+cardH,w,26),$"{heroes[selectedHero]}  •  {roles[selectedHero]}",small);float bw=Mathf.Min(390,w*.72f),bx=(Screen.width-bw)*.5f,by=Mathf.Max(top+cardH+168,Screen.height*.59f);if(GUI.Button(new Rect(bx,by,bw,68),"SPIELEN",primary))BeginLaunch();if(GUI.Button(new Rect(bx,by+82,bw,48),"HELDEN",button))page=Page.Heroes;GUI.enabled=false;GUI.Button(new Rect(bx,by+140,bw,44),"RANGLISTE  •  BALD",button);GUI.enabled=true;if(GUI.Button(new Rect(bx,by+196,bw,42),"EINSTELLUNGEN",button))page=Page.Settings;GUI.Label(new Rect(x,Screen.height-38,w,20),"ZWEI REALITÄTEN. EINE FRONT.",small);}
private void DrawHeroes(){float w=Mathf.Min(760,Screen.width*.9f),x=(Screen.width-w)*.5f,y=Screen.height*.22f;GUI.Label(new Rect(x,Screen.height*.07f,w,62),"WÄHLE DEINEN HELDEN",title);GUI.Box(new Rect(x,y,w,300),GUIContent.none,panel);float cw=Mathf.Min(210,w*.32f);StylizedHeroCard.Draw(new Rect(x+(w-cw)*.5f,y+20,cw,205),(HeroId)selectedHero,whiteTexture,Time.unscaledTime);if(GUI.Button(new Rect(x+18,y+95,55,55),"‹",button))ChangeHero(-1);if(GUI.Button(new Rect(x+w-73,y+95,55,55),"›",button))ChangeHero(1);GUI.Label(new Rect(x+70,y+222,w-140,42),heroes[selectedHero],heroName);GUI.Label(new Rect(x+70,y+260,w-140,30),$"{roles[selectedHero]}   •   {selectedHero+1}/{heroes.Length}",subtitle);if(GUI.Button(new Rect(x,y+322,180,46),"ZURÜCK",button))page=Page.Home;}
private void ChangeHero(int direction){selectedHero=(selectedHero+direction+heroes.Length)%heroes.Length;PlayerHeroSelection.Select((HeroId)selectedHero);}private void DrawSettings(){float w=Mathf.Min(620,Screen.width*.86f),x=(Screen.width-w)*.5f;GUI.Label(new Rect(x,Screen.height*.14f,w,62),"EINSTELLUNGEN",title);GUI.Box(new Rect(x,Screen.height*.30f,w,150),GUIContent.none,panel);GUI.Label(new Rect(x+25,Screen.height*.30f+30,w-50,34),"AUDIO, GRAFIK UND STEUERUNG",subtitle);GUI.Label(new Rect(x+25,Screen.height*.30f+78,w-50,28),"Wird nach dem Gameplay-Test aktiviert.",small);if(GUI.Button(new Rect(x,Screen.height*.30f+180,180,48),"ZURÜCK",button))page=Page.Home;}
private void BeginLaunch(){PlayerHeroSelection.Select((HeroId)selectedHero);launching=true;launchAt=Time.unscaledTime;}private void DrawLaunch(){float p=Mathf.Clamp01((Time.unscaledTime-launchAt)/.62f),ease=p*p*(3-2*p),w=Mathf.Lerp(Screen.width*.02f,Screen.width*.72f,ease);GUI.color=new Color(1,1,1,.12f+.65f*ease);GUI.DrawTexture(new Rect(Screen.width*.5f-w*.5f,0,w,Screen.height),whiteTexture);GUI.color=Color.white;GUI.Label(new Rect(0,Screen.height*.43f,Screen.width,70),p>.48f?"ENTER THE FRONT":"REALITY COLLISION",heroName);}private void EnterMatch(){visible=false;Time.timeScale=1;gameObject.SetActive(false);}
private void EnsureStyles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/18,34,66),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};subtitle=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/48,15,23),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};button=new GUIStyle(GUI.skin.button){fontSize=Mathf.Clamp(Screen.width/48,15,22),fontStyle=FontStyle.Bold};primary=new GUIStyle(button){fontSize=Mathf.Clamp(Screen.width/38,20,29)};small=new GUIStyle(GUI.skin.label){fontSize=13,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};panel=new GUIStyle(GUI.skin.box);heroName=new GUIStyle(title){fontSize=Mathf.Clamp(Screen.width/24,27,46)};sideLabel=new GUIStyle(small){fontSize=12,alignment=TextAnchor.MiddleCenter};}
}
}
